package com.autojobapply.discovery;
import java.net.*; import java.nio.file.*; import java.util.*;
/** Offline regression test; run as a Java main without Maven or internet. */
public final class GreenhouseOfflineTest { public static void main(String[] args)throws Exception{String dir=Files.readString(Path.of("src/test/resources/greenhouse/directory.json"));String jobs=Files.readString(Path.of("src/test/resources/greenhouse/jobs.json"));HttpTextClient fake=u->{String s=u.toString();if(s.contains("job-board-directory"))return dir;if(s.contains("valid/jobs?content=false"))return "{\"jobs\":[]}";if(s.contains("valid/jobs?content=true"))return jobs;throw new IllegalStateException("HTTP fixture failure");};GreenhouseCompanyDiscoveryService companies=new GreenhouseCompanyDiscoveryService(fake);var boards=companies.discover();check(boards.size()==1,"deduplication");check(companies.validate(boards.get(0)),"validation");var parsed=new GreenhouseJobDiscoveryService(fake).retrieve(boards.get(0));check(parsed.size()==1&&parsed.get(0).jobId().equals("123")&&parsed.get(0).description().contains("Java"),"job parsing");try{new GreenhouseJobDiscoveryService(u->{throw new IllegalStateException("HTTP 500");}).retrieve(boards.get(0));throw new AssertionError("API failure not propagated");}catch(IllegalStateException expected){}System.out.println("GREENHOUSE_OFFLINE_TEST_PASSED");}private static void check(boolean ok,String n){if(!ok)throw new AssertionError(n);}}
